            c.hidden=c.hidden||{}; c.order=c.order||{}; c.size=c.size||{}; c.titles=c.titles||{};
            c.radarHidden=c.radarHidden||{};
            // Zone und Groesse je nativer Karte. zone: links|mitte|rechts,
            // wh: {b:1..4 Breite, h:0..4 Hoehenstufe, 0 = automatisch}.
            // Beides ist seit der Layout-Engine v2 (14.08.) NUR noch Migrations-
