        function save(){ try{ localStorage.setItem(CFG_KEY, JSON.stringify(CFG)); }catch(e){} }
        function uid(){ return 'c'+Math.random().toString(36).slice(2,9); }

        var H = {
            esc:function(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); },
            num:function(n){ n=Number(n)||0; return (Math.round(n*10)/10).toString().replace('.',','); },
            std:function(code){ var M={ADP:'Alexandroupolis',AL:'Alanya',B:'Berlin',E:'Essen',P:'Potsdam',SER:'Serres',ZWT:'Zeitwert',NBB:'Neubrandenburg',SKA:'Sakarya'}; return M[code]||code||''; },
            flag:function(code){ return '<span class="b-flag">'+(code||'?')+'</span>'; },
            empty:function(t){ return '<div class="rc-info-empty">'+t+'</div>'; },
            rows:function(list, fn){ return list.map(fn).join(''); }
        };
        var esc = H.esc;

        // ---------- Datenkontext fuer Live-Module ----------
        // WICHTIG (16.08.): window.rcLetzteStats ist der UNGEFILTERTE Vollbestand
        // — der Dashboard-Filter (Standort/Team/Stack) wirkt erst im Renderer.
        // Genau deshalb kann ein Modul einen Standort- oder Laenderkampf zeigen,
        // waehrend das Dashboard global auf EINEN Standort gefiltert ist
        // (Nutzer-Vorgabe: "auch wenn ich die Laender gefiltert habe").
        // Den Zuschnitt bestimmt jedes Modul selbst ueber modScope(m).
        function D(){
            var st=window.rcLetzteStats||{}, ag=st.agentStats||{}, tm=st.teamStats||{}, sd=st.standortStats||{}, nt=st.nationStats||{};
            var bnt=function(o){ return Number(o.bnt)|| ((Number(o.kip)||0)+(Number(o.mob)||0)+(Number(o.env)||0)+(Number(o.fibDsl)||0)+(Number(o.ptv)||0)+(Number(o.sonstBnt)||0)); };
            var vvl=function(o){ return Number(o.vvl)|| ((Number(o.kipVvl)||0)+(Number(o.mobVvl)||0)+(Number(o.fibVvl)||0)); };
            return {
                agents:Object.keys(ag).map(function(k){ var a=ag[k]; return {name:a.name,standort:a.standort,team:a.team,ccsId:a.ccsId||'',kip:a.kip||0,mob:a.mob||0,env:a.env||0,ptv:a.ptv||0,fibDsl:a.fibDsl||0,vvl:vvl(a),bnt:bnt(a),ansprachen:a.ansprachen||0,kontakte:(a.kontakte||a.calls||0),offers:(a.offers!=null?a.offers:null)}; }),
                teams:Object.keys(tm).map(function(k){ var t=tm[k]; return {name:t.name,code:t.code,standort:t.standort,kip:t.kip||0,mob:t.mob||0,vvl:vvl(t),bnt:bnt(t),calls:t.calls||0}; }),
                standorte:Object.keys(sd).map(function(k){ var s=sd[k]; return {code:s.code||k,kip:s.kip||0,mob:s.mob||0,vvl:vvl(s),bnt:bnt(s),calls:(s.calls||s.pitches||0),pitches:(s.pitches||0),total:(s.total||0)}; }),
                kpis:Object.keys(window.rcKpiData||{}).map(function(k){ var x=window.rcKpiData[k]; return {agentName:x.agentName,standort:x.standort,cs:x.cs,tnps:x.tnps,ahtSec:x.ahtSec,callCount:x.callCount,fq:x.fq}; }),
                // Roh-Liga (ALLE Felder inkl. kpi.alle) fuer die Kennzahl-Module.
                // Bewusst als Referenz, nicht als Kopie: 500+ Agenten x 40 Felder
                // je 2-s-Takt zu klonen waere auf dem Wandmonitor spuerbar.
                ligaRoh:window.rcKpiData||{},
                // Nationen (Laenderkampf) — kommt aus derselben ungefilterten Quelle.
                nationen:Object.keys(nt).map(function(k){ var n=nt[k]; return {code:k,anzahl:n.anzahl||0,kip:n.kip||0,mob:n.mob||0,bnt:n.bnt||0,vvl:n.vvl||0}; }),
                // Einzelverkaeufe des Tages: DIE feinste Quelle (Uhrzeit, Produkt,
                // Standort, Team, Stueck) — Grundlage fuer Heatmap, Stundenkurve
                // je Standort, Produkt-Ranglisten und Ticker.
                sales:window.rcAllSales||[],
                rejections:window.rcAllRejections||[],
                stunden:window.rcHourStats||null,
                sum:function(key){ var s=0; Object.keys(ag).forEach(function(k){ s+=Number(ag[k][key])||0; }); return s; },
                now:new Date()
            };
        }

        // ============================================================
        //  BAUSTEINE FUER EIGENE MODULE (16.08. spaetabends)
        //  ----------------------------------------------------------
        //  Nutzer-Vorgabe: "Ich moechte Vielfalt haben und viel mehr
        //  Diagramme und Charts ... auch die Standort- und Laenderkaempfe
        //  sehen, auch wenn ich alleine waehle, zum Beispiel als Standort."
        //
        //  Drei Teile, in dieser Reihenfolge zu lesen:
        //   1. ZUSCHNITT  — jedes Modul entscheidet SELBST, wessen Zahlen es
        //      zeigt. 'dash' folgt dem Dashboard-Filter, alles andere ist
        //      davon unabhaengig (genau der Wunsch oben).
        //   2. KENNZAHLEN — EINE Registry statt acht fast gleicher Module.
        //      Sie kennt Quelle, Aggregationsart, Format, Ziel und Richtung.
        //   3. ZEICHNEN   — SVG nur fuer Geometrie, TEXT immer als HTML.
        //      Grund: eine Karte hat unbekannte Breite; Text im viewBox
        //      skaliert mit und wird auf schmalen Karten unlesbar klein —
        //      auf einem Wandmonitor der sichere Weg in die Unbrauchbarkeit.
        // ============================================================

        // ---------- 1. Zuschnitt je Modul ----------
        // Gespeichert wird EINE Zeichenkette (klein, migrationsfest):
        //   'dash'        folgt dem Dashboard-Filter (Vorgabe)
        //   'alle'        ignoriert den Filter komplett  <- Kaempfe
        //   'std:AL'      fester Standort
        //   'nation:TR'   festes Land
        //   'team:NAME'   festes Team
        function modScope(m){
            var s=(m&&m.scope)||'dash';
            var frei={ std:'ALL', team:'ALL', stack:'ALL', nation:'ALL', quelle:s, folgt:false };
            if(s==='alle') return frei;
            if(s.indexOf('std:')===0){ frei.std=s.slice(4); return frei; }
            if(s.indexOf('nation:')===0){ frei.nation=s.slice(7); return frei; }
            if(s.indexOf('team:')===0){ frei.team=s.slice(5); return frei; }
            if(s.indexOf('stack:')===0){ frei.stack=s.slice(6); return frei; }
            var a={ std:'ALL', team:'ALL', stack:'ALL' };
            try{ if(window.rcActiveScope) a=window.rcActiveScope(); }catch(e){}
            return { std:a.std||'ALL', team:a.team||'ALL', stack:a.stack||'ALL', nation:'ALL', quelle:'dash', folgt:true };
        }
        function modScopeText(sc){
            if(!sc) return '';
            if(sc.folgt){
                var t=[]; if(sc.std!=='ALL') t.push(H.std(sc.std));
                if(sc.team!=='ALL') t.push(sc.team);
                if(sc.stack!=='ALL') t.push(rcStackFilterText(sc.stack));
                return t.length? ('Dashboard-Filter: '+t.join(' / ')) : 'ganzes Haus';
            }
            if(sc.nation!=='ALL') return 'Land: '+mbNationName(sc.nation);
            if(sc.std!=='ALL') return H.std(sc.std);
            if(sc.team!=='ALL') return 'Team '+sc.team;
            if(sc.stack!=='ALL') return 'Stack '+sc.stack;
            return 'ganzes Haus (Filter bewusst ignoriert)';
        }
        function mbNation(code){ try{ var m=STANDORT_METADATA[code]; return (m&&m.nation)||''; }catch(e){ return ''; } }
        function mbNationName(n){ try{ return (NATION_METADATA[n]&&NATION_METADATA[n].name)||n; }catch(e){ return n; } }
        function mbNationFarbe(n){ try{ return (NATION_METADATA[n]&&NATION_METADATA[n].color)||'#8C8C8C'; }catch(e){ return '#8C8C8C'; } }
        function mbStdFarbe(code,i){ try{ return rcChartFarbe(code,i); }catch(e){ return '#0068A0'; } }
        // Gehoert ein Standort-Code in den Zuschnitt?
        function mbStdIn(code, sc){
            if(!sc) return true;
            if(sc.std!=='ALL' && code!==sc.std) return false;
            if(sc.nation!=='ALL' && mbNation(code)!==sc.nation) return false;
            return true;
        }
        // Team/Stack wirken nur ueber das Mapping — nie roh vergleichen.
        function mbAgentIn(a, sc){
            if(!mbStdIn(a.standort, sc)) return false;
            if(sc.team!=='ALL' && a.team!==sc.team) return false;
            // Die EINE Stack-Regel (05.10.): Mapping, sonst Anker; 'P:<projekt>'
            // nimmt das ganze Projekt — nie selbst gegen stackMap vergleichen.
            if(sc.stack!=='ALL' && !rcStackFilterPasst(a.team, sc.stack, a.projekt)) return false;
            return true;
        }
        // ---------- Der ungefilterte Agenten-Bestand ----------
        // GEMESSEN am 16.08. (nicht angenommen — genau diese Annahme war zuerst
        // falsch): window.rcLetzteStats ist NICHT der Vollbestand. Der
        // Dashboard-Filter wirkt schon beim Parsen (processDataStream, inScope),
        // bei Filter "Alanya" stehen in standortStats/agentStats nur Alanya-
        // Zahlen. Ungefiltert ueberleben ausschliesslich die Quellen, die fuer
        // die Kriegskarte gebaut werden:
        //   window.rcAllSales      jeder Abschluss (Standort, Team, vo, cat, anzahl)
        //   window.rcWarStdFull    Mengen + Ansprachen je Standort
        //   window.rcWarBoteCands  Ansprachen je Agent
        // Ein Modul mit freiem Zuschnitt MUSS daraus rechnen, sonst zeigt es
        // beim gefilterten Dashboard heimlich zu wenig — und behauptet dabei
        // "Filter bewusst ignoriert".
        // NICHT ungefiltert verfuegbar: ESL-Kontakte (und Ansprachen unterhalb
        // der Standort-Ebene fuer Agenten ohne Verkauf). Die liefern dann
        // ehrlich null statt einer stillen 0.
        function mbLeerAgent(vo, name, team, std){
            return { vo:vo, name:name, team:team, standort:std, ccsId:'',
                     kip:0, mob:0, env:0, ptv:0, fibDsl:0, sonstBnt:0, kipVvl:0, mobVvl:0, fibVvl:0,
                     bnt:0, vvl:0, ansprachen:0, kontakte:null };
        }
        function mbAgentenFrei(sc){
            var per={};
            (window.rcAllSales||[]).forEach(function(v){
                if(!mbStdIn(v.standort, sc)) return;
                if(sc.team!=='ALL' && v.team!==sc.team) return;
                if(sc.stack!=='ALL' && !rcStackFilterPasst(v.team, sc.stack, v.projekt)) return;
                var k=v.vo||v.name; if(!k) return;
                var a=per[k]||(per[k]=mbLeerAgent(v.vo, v.name, v.team, v.standort));
                var n=Number(v.anzahl)||1;
                if(v.cat && a[v.cat]!=null) a[v.cat]+=n;
                if(v.isBnt) a.bnt+=n;
                if(v.isVvl) a.vvl+=n;
            });
            // Ansprachen aus dem ungefilterten Boten-Bestand nachtragen. Agenten
            // OHNE Abschluss kommen erst hier dazu — sonst fehlten genau die,
            // die viel ansprechen und nichts abschliessen.
            (window.rcWarBoteCands||[]).forEach(function(b){
                if(!mbStdIn(b.standort, sc)) return;
                var k=b.vo||b.name; if(!k) return;
                var a=per[k];
                if(!a){
                    // Team/Stack sind aus dem Boten-Bestand nicht bekannt —
                    // bei einem Team-/Stack-Zuschnitt wird deshalb NICHT geraten.
                    if(sc.team!=='ALL'||sc.stack!=='ALL') return;
                    a=per[k]=mbLeerAgent(b.vo, b.name, '', b.standort);
                }
                a.ansprachen=Number(b.ansp)||0;
            });
            return Object.keys(per).map(function(k){ return per[k]; });
        }
        // Folgt das Modul dem Dashboard, ist der gefilterte Bestand genau richtig
        // (und vollstaendiger: er kennt auch die Kontakte). Nur beim freien
        // Zuschnitt wird umgeschaltet.
        function mbAgenten(d, sc){
            if(sc && sc.folgt===false) return mbAgentenFrei(sc);
            return (d.agents||[]).filter(function(a){ return mbAgentIn(a, sc); });
        }
        function mbTeams(d, sc){
            return (d.teams||[]).filter(function(t){
                if(!mbStdIn(t.standort, sc)) return false;
                if(sc.team!=='ALL' && t.name!==sc.team) return false;
                if(sc.stack!=='ALL' && !rcStackFilterPasst(t.name, sc.stack)) return false;
                return true;
            });
        }
        function mbStandorte(d, sc){ return (d.standorte||[]).filter(function(s){ return mbStdIn(s.code, sc); }); }
        function mbSales(d, sc){
            return (d.sales||[]).filter(function(v){
                if(!mbStdIn(v.standort, sc)) return false;
                if(sc.team!=='ALL' && v.team!==sc.team) return false;
                // Der Stack fehlte hier (05.10.): d.sales ist die UNGEFILTERTE Liste, eine
                // Kachel unter Stack-Filter zeigte die Verkaeufe aller Stacks.
                if(sc.stack!=='ALL' && !rcStackFilterPasst(v.team, sc.stack, v.projekt)) return false;
                return true;
            });
        }
        // Liga-Zeilen IMMER ueber rcLigaInScope/rcLigaMeta (Fallstrick: Liga-Team
        // ist eine NUMMER, das Dashboard filtert auf den NAMEN). Der Nation-Filter
        // kommt danach obendrauf, den kennt rcLigaInScope nicht.
        function mbLiga(sc){
            var roh=window.rcKpiData||{}, out=[];
            Object.keys(roh).forEach(function(id){
                var k=roh[id]; if(!k) return;
                try{ if(window.rcLigaInScope && !window.rcLigaInScope(k, {std:sc.std,team:sc.team,stack:sc.stack})) return; }catch(e){}
                if(sc.nation!=='ALL'){
                    var meta={}; try{ meta=window.rcLigaMeta(k)||{}; }catch(e){}
                    if(mbNation(meta.std)!==sc.nation) return;
                }
                out.push(k);
            });
            return out;
        }
        function mbLigaCalls(sc){
            try{ return window.rcLigaAggScope({std:sc.std,team:sc.team,stack:sc.stack}); }
            catch(e){ return {byStd:{},byTeam:{},total:0}; }
        }

        // ---------- 2. Kennzahl-Registry ----------
        //  EINE Stelle, die weiss: woher kommt der Wert, wie wird er ueber
        //  mehrere Agenten zusammengefasst, wie wird er geschrieben, wann ist
        //  er gut. Ein Modul nennt nur noch die id.
        //  art: 'summe'  Stueckzahlen        -> addieren
        //       'quote'  Prozent aus z/n     -> POOLEN (nie mitteln!)
        //       'zeit'   Sekunden je Call    -> rcZeitMittel (eigener Nenner)
        //       'menge'  Calls               -> addieren
        var MB_KENN = {
            bnt:        {label:'BNT gesamt',        quelle:'esl', feld:'bnt',        art:'summe', fmt:'stk',  hoch:true},
            kip:        {label:'KIP-BNT',           quelle:'esl', feld:'kip',        art:'summe', fmt:'stk',  hoch:true},
            mob:        {label:'Mobilfunk-BNT',     quelle:'esl', feld:'mob',        art:'summe', fmt:'stk',  hoch:true},
            vvl:        {label:'VVL',               quelle:'esl', feld:'vvl',        art:'summe', fmt:'stk',  hoch:true},
            env:        {label:'Entertain/TV',      quelle:'esl', feld:'env',        art:'summe', fmt:'stk',  hoch:true},
            ptv:        {label:'PTV',               quelle:'esl', feld:'ptv',        art:'summe', fmt:'stk',  hoch:true},
            fibDsl:     {label:'Fibre/DSL',         quelle:'esl', feld:'fibDsl',     art:'summe', fmt:'stk',  hoch:true},
            ansprachen: {label:'Ansprachen',        quelle:'esl', feld:'ansprachen', art:'summe', fmt:'stk',  hoch:true},
            kontakte:   {label:'ESL-Kontakte',      quelle:'esl', feld:'kontakte',   art:'summe', fmt:'stk',  hoch:true},
            offers:     {label:'Angebote offen',    quelle:'esl', feld:'offers',     art:'summe', fmt:'stk',  hoch:false},
            calls:      {label:'Calls (Ligaliste)', quelle:'liga',feld:'callCount',  art:'menge', fmt:'stk',  hoch:true, ziel:'calls'},
            cs:         {label:'CS',                quelle:'liga',feld:'cs',    z:'csZ',   n:'csN',   art:'quote', fmt:'proz', hoch:true,  ziel:'cs'},
            tnps:       {label:'TNPS',              quelle:'liga',feld:'tnps',  z:'tnpsZ', n:'tnpsN', art:'quote', fmt:'proz', hoch:true,  ziel:'tnps'},
            fq:         {label:'TNPS-Antwortquote', quelle:'liga',feld:'fq',    z:'fqZ',   n:'fqN',   art:'quote', fmt:'proz', hoch:true,  ziel:'fq'},
            dds:        {label:'Deep Detractor',    quelle:'liga',feld:'dds',   z:'ddsZ',  n:'ddsN',  art:'quote', fmt:'proz', hoch:false, ziel:'dds'},
            ff7:        {label:'FF7',               quelle:'liga',feld:'ff7',   n:'ff7N',  art:'quote', fmt:'proz', hoch:true,  ziel:'ff7'},
            ftf:        {label:'First-Time-Fix',    quelle:'liga',feld:'ftf',   z:'ftfZ',  n:'ftfN',  art:'quote', fmt:'proz', hoch:true},
            wq:         {label:'Weiterleitungen',   quelle:'liga',feld:'wq',    art:'quote', fmt:'proz', hoch:false},
            ahtSec:     {label:'AHT (Gespraech+Nacharbeit)', quelle:'liga', feld:'ahtSec',  art:'zeit', fmt:'zeit', hoch:false, ziel:'ahtSek'},
            acwSec:     {label:'ACW (Nacharbeit)',  quelle:'liga',feld:'acwSec',  art:'zeit', fmt:'zeit', hoch:false, ziel:'acwSek'},
            achtSec:    {label:'ACHT (Haltezeit)',  quelle:'liga',feld:'achtSec', art:'zeit', fmt:'zeit', hoch:false, ziel:'achtSek'},
            acdSec:     {label:'ACD (Gespraech)',   quelle:'liga',feld:'acdSec',   art:'zeit', fmt:'zeit', hoch:false}
        };
        // Ziel-Vorgabe je Kennzahl. AHT steht in RC_ZIELE in MINUTEN, die
        // Kennzahl liefert SEKUNDEN — einmal hier umgerechnet, statt an jeder
        // Zeichenstelle neu (dort wurde es im Projekt schon einmal vergessen).
        function mbZiel(kenn){
            if(!kenn||!kenn.ziel) return null;
            try{
                if(kenn.ziel==='ahtSek'){ var z=RC_ZIELE.ahtMin||{}; return {max:(z.max||13)*60, opt:(z.opt||10)*60}; }
                return RC_ZIELE[kenn.ziel]||null;
            }catch(e){ return null; }
        }
        function mbKenn(id){ return MB_KENN[id] || MB_KENN.bnt; }
        function mbKennListe(){ return Object.keys(MB_KENN); }
        // Die Auflegerquote ist nirgends mehr sichtbar (Nutzer-Entscheidung 30.10.) — auch nicht
        // als "freie Portal-Kennzahl" aus kpi.alle (alphabetisch waere sie sogar die erste).
        function mbPortalName(n){ return !/^auflegerquote/i.test(String(n)); }
        // Der Wert einer Kennzahl fuer eine MENGE von Agenten/Einheiten.
        // Liefert {wert, n, geliefert} — 'geliefert:false' heisst "die
        // Ligaliste hat diese Spalte gar nicht geschickt" und ist etwas
        // anderes als der Wert 0 (Lehre vom 16.08., ACW/ACHT).
        function mbWert(kennId, esl, liga){
            var kenn=mbKenn(kennId);
            if(kenn.quelle==='esl'){
                // null heisst "diese Groesse gibt es in diesem Zuschnitt nicht"
                // (z.B. ESL-Kontakte beim freien Zuschnitt) — und ist etwas
                // anderes als die Zahl 0. Eine stille 0 waere hier die
                // gefaehrlichere Luege, weil sie echt aussieht.
                var s=0, da=false;
                (esl||[]).forEach(function(a){ var v=a[kenn.feld]; if(v==null) return; da=true; s+=Number(v)||0; });
                return { wert:da?s:null, n:(esl||[]).length, geliefert:da };
            }
            var L=liga||[];
            if(!L.length) return { wert:null, n:0, geliefert:false };
            if(kenn.art==='menge'){
                var c=0, da=false;
                L.forEach(function(k){ if(k[kenn.feld]!=null){ da=true; c+=Number(k[kenn.feld])||0; } });
                return { wert:da?c:null, n:L.length, geliefert:da };
            }
            if(kenn.art==='zeit'){
                var m; try{ m=rcZeitMittel(L, kenn.feld); }catch(e){ m={sek:null,n:0,geliefert:false}; }
                return { wert:m.sek, n:m.n, geliefert:m.geliefert };
            }
            // quote: POOLEN wie rcTeamQualiAgg (Zaehler/Nenner), Mittelwert nur
            // als Rueckfall, wenn die Ligaliste keine Zaehler/Nenner liefert.
            var z=0, n=0, hat=false, mw=[], da=false;
            L.forEach(function(k){
                if(k[kenn.feld]!=null){ da=true; mw.push(Number(k[kenn.feld])||0); }
                if(kenn.z && kenn.n && k[kenn.z]!=null && k[kenn.n]>0){ z+=Number(k[kenn.z])||0; n+=Number(k[kenn.n])||0; hat=true; }
            });
            if(hat && n>0) return { wert:z/n*100, n:n, geliefert:true };
            if(mw.length) return { wert:mw.reduce(function(a,b){return a+b;},0)/mw.length, n:mw.length, geliefert:true };
            return { wert:null, n:0, geliefert:da };
        }
        // Wert je Einheit (Agent/Team/Standort/Nation) — die gemeinsame Basis
        // aller Ranglisten, Balken und Streudiagramme.
        function mbEinheiten(d, sc, ebene){
            var out=[];
            if(ebene==='nation'){
                var perN={};
                mbAgenten(d, sc).forEach(function(a){
                    var nn=mbNation(a.standort)||'?';
                    (perN[nn]=perN[nn]||{key:nn, name:mbNationName(nn), farbe:mbNationFarbe(nn), esl:[], liga:[]}).esl.push(a);
                });
                mbLiga(sc).forEach(function(k){
                    var meta={}; try{ meta=window.rcLigaMeta(k)||{}; }catch(e){}
                    var nn=mbNation(meta.std)||'?';
                    (perN[nn]=perN[nn]||{key:nn, name:mbNationName(nn), farbe:mbNationFarbe(nn), esl:[], liga:[]}).liga.push(k);
                });
                out=Object.keys(perN).map(function(k){ return perN[k]; });
            } else if(ebene==='standort'){
                var perS={};
                mbAgenten(d, sc).forEach(function(a){
                    var c=a.standort||'?';
                    (perS[c]=perS[c]||{key:c, name:H.std(c), farbe:mbStdFarbe(c), esl:[], liga:[]}).esl.push(a);
                });
                mbLiga(sc).forEach(function(k){
                    var meta={}; try{ meta=window.rcLigaMeta(k)||{}; }catch(e){}
                    var c=meta.std||'?';
                    (perS[c]=perS[c]||{key:c, name:H.std(c), farbe:mbStdFarbe(c), esl:[], liga:[]}).liga.push(k);
                });
                out=Object.keys(perS).map(function(k){ return perS[k]; });
            } else if(ebene==='team'){
                var perT={};
                mbAgenten(d, sc).forEach(function(a){
                    var t=a.team||'(ohne Team)';
                    (perT[t]=perT[t]||{key:t, name:t, farbe:mbStdFarbe(a.standort), std:a.standort, esl:[], liga:[]}).esl.push(a);
                });
                mbLiga(sc).forEach(function(k){
                    var meta={}; try{ meta=window.rcLigaMeta(k)||{}; }catch(e){}
                    var t=meta.team||'(ohne Team)';
                    (perT[t]=perT[t]||{key:t, name:t, farbe:mbStdFarbe(meta.std), std:meta.std, esl:[], liga:[]}).liga.push(k);
                });
                out=Object.keys(perT).map(function(k){ return perT[k]; });
            } else {
                // Agenten: Liga-Zeile ueber rcKpiForAgent dazuholen (CCS-Join,
                // Rueckfall auf den normierten Namen — steckt schon dort drin).
                var ligaAlle=mbLiga(sc), nurDa={};
                ligaAlle.forEach(function(k){ if(k.ccsId) nurDa[k.ccsId]=k; });
                out=mbAgenten(d, sc).map(function(a){
                    var k=null;
                    try{ k=window.rcKpiForAgent?window.rcKpiForAgent(a):null; }catch(e){}
                    if(k && k.ccsId && !nurDa[k.ccsId]) k=null;   // Liga-Zeile ausserhalb des Zuschnitts
                    return {key:a.vo||a.name, name:a.name, farbe:mbStdFarbe(a.standort), std:a.standort, team:a.team, esl:[a], liga:k?[k]:[]};
                });
            }
            // KEIN zweiter Aufbau fuer den freien Zuschnitt: mbAgenten oben
            // schaltet bereits auf mbAgentenFrei um, und mbLiga liefert die
            // Liga-Zeilen unabhaengig davon. Ein Nachbau an dieser Stelle hat
            // im Test genau eine Klasse Einheiten verschluckt — die mit
            // Liga-Daten, aber ohne Verkauf (ein Team, das telefoniert und
            // heute nichts abgeschlossen hat, verschwand aus der
            // Qualitaets-Rangliste). Gefunden durch den Vergleich mit einem
            // unabhaengig gerechneten Sollwert, nicht durch Hinsehen.
            return out;
        }
        function mbEinheitWert(e, kennId){ return mbWert(kennId, e.esl, e.liga); }

        // ---------- 3. Zeichen-Bausteine ----------
        //  Regel: SVG zeichnet GEOMETRIE, HTML schreibt TEXT. Beschriftung im
        //  viewBox skaliert mit der Kartenbreite und wird unlesbar.
        function mbFmt(wert, kennId){
            if(wert==null) return '&mdash;';
            var kenn=mbKenn(kennId);
            if(kenn.fmt==='zeit'){ var s=Math.max(0,Math.round(wert)), mm=Math.floor(s/60), ss=s%60; return mm+':'+(ss<10?'0':'')+ss+' Min'; }
            if(kenn.fmt==='proz') return H.num(wert)+' %';
            return H.num(wert);
        }
        function mbFarbe(wert, kennId){
            var kenn=mbKenn(kennId), ziel=mbZiel(kenn);
            if(wert==null||!ziel) return null;
            try{ return zielColor(wert, ziel); }catch(e){ return null; }
        }
        function mbLeer(text){ return H.empty(text); }
        // Warum fehlt ein Wert? Der Unterschied ist fuer den Nutzer wichtig:
        // "die Ligaliste schickt die Spalte nicht" ist etwas anderes als
        // "diese Groesse gibt es mit freiem Zuschnitt nicht".
        function mbFehltGrund(kenn, sc){
            if(kenn.quelle==='liga') return RC_ZEIT_FEHLT;
            if(sc && sc.folgt===false)
                return 'Diese Groesse wird beim Auswerten nur fuer den gefilterten Bereich mitgeschrieben — mit freiem Zuschnitt gibt es sie nicht. '
                     + 'Entweder den Zuschnitt auf "folgt dem Dashboard-Filter" stellen oder eine andere Kennzahl waehlen.';
            return 'Fuer diesen Zuschnitt liegen noch keine Zahlen vor.';
        }
        // Kopfzeile mit Zuschnitt — der Nutzer muss auf einen Blick sehen,
        // WESSEN Zahlen die Kachel zeigt. Ohne das ist ein Modul mit eigenem
        // Zuschnitt neben einem gefilterten Dashboard schlicht irrefuehrend.
        function mbKopf(sc, zusatz){
            var t=modScopeText(sc);
            return '<div class="rc-mb-kopf"><span'+(sc&&!sc.folgt?' class="frei"':'')+'>'+esc(t)+'</span>'+(zusatz?'<span>'+zusatz+'</span>':'')+'</div>';
        }
        // Waagerechte Balken-Rangliste (HTML — Text bleibt scharf).
        function mbBalken(zeilen, opt){
            opt=opt||{};
            var max=0; zeilen.forEach(function(z){ var v=Math.abs(Number(z.wert)||0); if(v>max) max=v; });
            if(opt.max!=null && opt.max>max) max=opt.max;
            if(!(max>0)) max=1;
            return '<div class="rc-mb-bars">'+zeilen.map(function(z,i){
                var v=Number(z.wert), br=(v==null||isNaN(v))?0:Math.max(0,Math.min(100,Math.abs(v)/max*100));
                var f=z.farbe||'#0068A0';
                return '<div class="rc-mb-bar">'
                    +'<div class="rc-mb-bl"><span class="rc-mb-bn">'+(opt.rang?'<b class="rc-mb-rang'+(i===0?' gold':'')+'">'+(i+1)+'</b>':'')+(z.flagge?H.flag(z.flagge)+' ':'')+esc(z.name)+'</span>'
                    +'<span class="rc-mb-bv"'+(z.wertFarbe?' style="color:'+z.wertFarbe+'"':'')+'>'+(z.text!=null?z.text:mbFmt(v,opt.kenn))+(z.zusatz?'<i>'+z.zusatz+'</i>':'')+'</span></div>'
                    +'<div class="rc-mb-bt"><i style="width:'+br.toFixed(1)+'%; background:'+f+';"></i>'
                    +(opt.ziel!=null&&max>0?'<u style="left:'+Math.max(0,Math.min(100,opt.ziel/max*100)).toFixed(1)+'%"></u>':'')+'</div></div>';
            }).join('')+'</div>';
        }
        // Gestapelte Anteile in EINER Zeile (Produktmix, Nationen-Anteil).
        function mbStapel(teile, gesamt){
            var sum=gesamt||teile.reduce(function(a,t){ return a+(Number(t.wert)||0); },0);
            if(!(sum>0)) return mbLeer('Noch nichts zu verteilen.');
            var br=[]; try{ br=rcBandBreiten(teile.map(function(t){ return Number(t.wert)||0; }), 100); }
            catch(e){ br=teile.map(function(t){ return (Number(t.wert)||0)/sum*100; }); }
            return '<div class="rc-mb-stapel">'+teile.map(function(t,i){
                return '<i style="width:'+(br[i]||0).toFixed(2)+'%; background:'+(t.farbe||'#0068A0')+';" title="'+esc(t.name)+': '+H.num(t.wert)+'"></i>';
            }).join('')+'</div>'
            +'<div class="rc-mb-leg">'+teile.map(function(t,i){
                return '<span><i style="background:'+(t.farbe||'#0068A0')+'"></i>'+esc(t.name)+' <b>'+H.num(t.wert)+'</b></span>';
            }).join('')+'</div>';
        }
        // Linien-/Flaechendiagramm. reihen = [{punkte:[..], farbe, gestrichelt}]
        function mbLinie(reihen, opt){
            opt=opt||{};
            var n=0; reihen.forEach(function(r){ if(r.punkte.length>n) n=r.punkte.length; });
            if(n<2) return mbLeer(opt.leer||'Noch zu wenig Verlauf.');
            var max=0; reihen.forEach(function(r){ r.punkte.forEach(function(v){ if(v>max) max=v; }); });
            if(!(max>0)) max=1;
            var W=300, Hh=opt.hoch||96, pad=6;
            var pfad=function(p){ return p.map(function(v,i){
                return (pad+i*(W-2*pad)/(n-1)).toFixed(1)+','+(Hh-pad-((Number(v)||0)/max)*(Hh-2*pad)).toFixed(1); }).join(' '); };
            var svg='<svg class="rc-mb-svg" viewBox="0 0 '+W+' '+Hh+'" preserveAspectRatio="none" role="img">';
            if(opt.raster){ [0.25,0.5,0.75].forEach(function(q){ var y=(Hh-pad-q*(Hh-2*pad)).toFixed(1); svg+='<line x1="'+pad+'" y1="'+y+'" x2="'+(W-pad)+'" y2="'+y+'" stroke="#2C2C2C" stroke-width="1"/>'; }); }
            reihen.forEach(function(r){
                var p=pfad(r.punkte);
                if(r.flaeche) svg+='<polygon points="'+p+' '+(W-pad)+','+(Hh-pad)+' '+pad+','+(Hh-pad)+'" fill="'+(r.farbe||'#0068A0')+'" opacity="0.16"/>';
                svg+='<polyline points="'+p+'" fill="none" stroke="'+(r.farbe||'#0068A0')+'" stroke-width="'+(r.gestrichelt?1.5:2.5)+'"'+(r.gestrichelt?' stroke-dasharray="4,3"':'')+' vector-effect="non-scaling-stroke"/>';
            });
            svg+='</svg>';
            return svg;
        }
        // Ring/Donut ueber stroke-dasharray — ein Kreis, keine Pfad-Rechnerei.
        function mbRing(teile, mitte, unten){
            var sum=teile.reduce(function(a,t){ return a+(Number(t.wert)||0); },0);
            if(!(sum>0)) return mbLeer('Noch keine Anteile.');
            var U=2*Math.PI*40, pos=0;
            var svg='<svg class="rc-mb-ring" viewBox="0 0 100 100" role="img"><g transform="rotate(-90 50 50)">';
            teile.forEach(function(t){
                var anteil=(Number(t.wert)||0)/sum, laenge=anteil*U;
                svg+='<circle cx="50" cy="50" r="40" fill="none" stroke="'+(t.farbe||'#0068A0')+'" stroke-width="16"'
                    +' stroke-dasharray="'+laenge.toFixed(2)+' '+(U-laenge).toFixed(2)+'" stroke-dashoffset="'+(-pos).toFixed(2)+'"/>';
                pos+=laenge;
            });
            svg+='</g></svg>';
            return '<div class="rc-mb-ringbox">'+svg+'<div class="rc-mb-ringtxt"><b>'+mitte+'</b>'+(unten?'<span>'+unten+'</span>':'')+'</div></div>';
        }
        // Tacho: Halbkreis von links nach rechts.
        function mbTacho(anteil, farbe, gross, klein){
            var a=Math.max(0,Math.min(1,Number(anteil)||0));
            var U=Math.PI*40, l=a*U;
            return '<div class="rc-mb-tachobox">'
                +'<svg class="rc-mb-tacho" viewBox="0 0 100 56" role="img">'
                +'<path d="M10 50 A40 40 0 0 1 90 50" fill="none" stroke="#2C2C2C" stroke-width="11" stroke-linecap="round"/>'
                +'<path d="M10 50 A40 40 0 0 1 90 50" fill="none" stroke="'+(farbe||'#0068A0')+'" stroke-width="11" stroke-linecap="round"'
                +' stroke-dasharray="'+l.toFixed(2)+' '+(U-l).toFixed(2)+'"/></svg>'
                +'<div class="rc-mb-tachotxt"><b'+(farbe?' style="color:'+farbe+'"':'')+'>'+gross+'</b>'+(klein?'<span>'+klein+'</span>':'')+'</div></div>';
        }
        // Heatmap als CSS-Raster (kein SVG: die Zellen tragen Text).
        function mbHeat(kopf, zeilen, opt){
            opt=opt||{};
            var max=0; zeilen.forEach(function(z){ z.werte.forEach(function(v){ if((Number(v)||0)>max) max=Number(v)||0; }); });
            if(!(max>0)) max=1;
            var basis=opt.farbe||'#0068A0';
            var h='<div class="rc-mb-heat" style="grid-template-columns:minmax(52px,auto) repeat('+kopf.length+',1fr);">';
            h+='<span class="rc-mb-hk"></span>'+kopf.map(function(k){ return '<span class="rc-mb-hk">'+esc(k)+'</span>'; }).join('');
            zeilen.forEach(function(z){
                h+='<span class="rc-mb-hz">'+(z.flagge?H.flag(z.flagge):esc(z.name))+'</span>';
                h+=z.werte.map(function(v){
                    var w=Number(v)||0, a=w>0?(0.15+0.85*(w/max)):0;
                    return '<span class="rc-mb-hc" style="background:'+(w>0?basis:'#1A1A1A')+'; opacity:'+(w>0?a.toFixed(2):'1')+';" title="'+esc(z.name)+': '+w+'">'+(w>0?w:'')+'</span>';
                }).join('');
            });
            return h+'</div>';
        }
        // Streudiagramm: zwei Kennzahlen gegeneinander.
        function mbStreu(punkte, opt){
            opt=opt||{};
            if(!punkte.length) return mbLeer('Keine Punkte im Zuschnitt.');
            var xs=punkte.map(function(p){return p.x;}), ys=punkte.map(function(p){return p.y;});
            var xMax=Math.max.apply(null,xs)||1, yMax=Math.max.apply(null,ys)||1;
            var xMin=Math.min.apply(null,xs), yMin=Math.min.apply(null,ys);
            if(xMax===xMin) xMax=xMin+1; if(yMax===yMin) yMax=yMin+1;
            var W=300, Hh=opt.hoch||130, pad=8;
            var sx=function(v){ return (pad+((v-xMin)/(xMax-xMin))*(W-2*pad)).toFixed(1); };
            var sy=function(v){ return (Hh-pad-((v-yMin)/(yMax-yMin))*(Hh-2*pad)).toFixed(1); };
            var svg='<svg class="rc-mb-svg" viewBox="0 0 '+W+' '+Hh+'" preserveAspectRatio="none" role="img">';
            if(opt.zielX!=null && opt.zielX>=xMin && opt.zielX<=xMax) svg+='<line x1="'+sx(opt.zielX)+'" y1="'+pad+'" x2="'+sx(opt.zielX)+'" y2="'+(Hh-pad)+'" stroke="#EB9700" stroke-width="1" stroke-dasharray="3,3" vector-effect="non-scaling-stroke"/>';
            if(opt.zielY!=null && opt.zielY>=yMin && opt.zielY<=yMax) svg+='<line x1="'+pad+'" y1="'+sy(opt.zielY)+'" x2="'+(W-pad)+'" y2="'+sy(opt.zielY)+'" stroke="#EB9700" stroke-width="1" stroke-dasharray="3,3" vector-effect="non-scaling-stroke"/>';
            punkte.forEach(function(p){
                svg+='<circle cx="'+sx(p.x)+'" cy="'+sy(p.y)+'" r="'+(p.gross||3.5)+'" fill="'+(p.farbe||'#0068A0')+'" opacity="0.85" vector-effect="non-scaling-stroke"><title>'+esc(p.name||'')+'</title></circle>';
            });
            return svg+'</svg>';
        }
        // Grosse Zahl mit Zusatzzeile (Wandmonitor-tauglich).
        function mbZahl(gross, klein, farbe, trend){
            return '<div class="rc-mb-zahl"><b'+(farbe?' style="color:'+farbe+'"':'')+'>'+gross+'</b>'
                +(trend?'<span class="rc-mb-trend '+(trend.hoch?'auf':'ab')+'">'+(trend.hoch?'&#9650;':'&#9660;')+' '+trend.text+'</span>':'')
                +(klein?'<span class="rc-mb-zk">'+klein+'</span>':'')+'</div>';
        }
        // Tabelle mit Zebra und Ampelkante.
        function mbTabelle(kopf, zeilen){
            return '<table class="b-table rc-mb-tab"><thead><tr>'+kopf.map(function(k){ return '<th>'+esc(k)+'</th>'; }).join('')+'</tr></thead><tbody>'
                +zeilen.map(function(z){
                    return '<tr'+(z.kante?' style="box-shadow:inset 3px 0 0 '+z.kante+'"':'')+'>'
                        +z.zellen.map(function(c,i){ return '<td'+(c&&c.farbe?' style="color:'+c.farbe+'"':'')+'>'+((c&&c.text!=null)?c.text:(c==null?'':c))+'</td>'; }).join('')+'</tr>';
                }).join('')+'</tbody></table>';
        }

        // ---------- Modultypen (Inhalt + Live) ----------
        function lead(mod,d,key,unit){ var lim=Number(mod.limit)||8;
            var list=(d.agents||[]).filter(function(a){return (Number(a[key])||0)>0;}).sort(function(a,b){return (Number(b[key])||0)-(Number(a[key])||0);}).slice(0,lim);
            if(!list.length) return H.empty('Noch keine '+unit+' — Platz 1 ist frei!');
            return '<ol class="b-rank">'+H.rows(list,function(a,i){ return '<li><span class="b-pos '+(i===0?'gold':'')+'">'+(i+1)+'</span><span class="b-nm">'+H.flag(a.standort)+' '+esc(a.name)+'</span><span class="b-val">'+(Number(a[key])||0)+'</span></li>'; })+'</ol>'; }
