                    Object.keys(_ag).forEach(function(k){ var t=_ag[k].team; if(t&&_tm.indexOf(t)<0) _tm.push(t); });
                    var _sm2=(window.rcWcaMapping&&window.rcWcaMapping.stackMap)||{};
