                var _tmOpt='<option value="ALL"'+(!rc.team||rc.team==='ALL'?' selected':'')+'>Alle Teams</option>'+_fehlOpt(rc.team,_tm.indexOf(rc.team)>=0)+_tm.sort().map(function(t){ return '<option value="'+esc(t)+'"'+(rc.team===t?' selected':'')+'>'+esc(t)+'</option>'; }).join('');
                h+=rowr('Team', '<select id="cfgRepTeam" class="rc-cfg-txt" style="width:170px;">'+_tmOpt+'</select>');
